100	void LV_ATTRIBUTE_FAST_MEM lv_draw_label(lv_layer_t * layer, const lv_draw_label_dsc_t * dsc,
101	                                         const lv_area_t * coords)
102	{
103	    if(dsc->opa <= LV_OPA_MIN) return;
104	    if(dsc->text == NULL || dsc->text[0] == '\0') return;
105	    if(dsc->font == NULL) {
106	        LV_LOG_WARN("dsc->font == NULL");
107	        return;
108	    }
109	
110	    LV_PROFILER_DRAW_BEGIN;
111	    lv_draw_task_t * t = lv_draw_add_task(layer, coords, LV_DRAW_TASK_TYPE_LABEL);
112	
113	    lv_memcpy(t->draw_dsc, dsc, sizeof(*dsc));
114	
115	    /*The text is stored in a local variable so malloc memory for it*/
116	    if(dsc->text_local) {
117	        lv_draw_label_dsc_t * new_dsc = t->draw_dsc;
118	        new_dsc->text = lv_strndup(dsc->text, dsc->text_length);
119	        LV_ASSERT_MALLOC(new_dsc->text);
120	    }
121	
122	    lv_draw_finalize_task_creation(layer, t);
123	    LV_PROFILER_DRAW_END;
124	}
