126	void LV_ATTRIBUTE_FAST_MEM lv_draw_character(lv_layer_t * layer, lv_draw_label_dsc_t * dsc,
127	                                             const lv_point_t * point, uint32_t unicode_letter)
128	{
129	    if(dsc->opa <= LV_OPA_MIN) return;
130	    if(dsc->font == NULL) {
131	        LV_LOG_WARN("dsc->font == NULL");
132	        return;
133	    }
134	
135	    if(lv_text_is_marker(unicode_letter)) return;
136	
137	    LV_PROFILER_DRAW_BEGIN;
138	
139	    lv_font_glyph_dsc_t g;
140	    lv_font_get_glyph_dsc(dsc->font, &g, unicode_letter, 0);
141	
142	    lv_area_t a;
143	    a.x1 = point->x;
144	    a.y1 = point->y;
145	    a.x2 = a.x1 + g.adv_w;
146	    a.y2 = a.y1 + lv_font_get_line_height(g.resolved_font ? g.resolved_font : dsc->font);
147	
148	    /*lv_draw_label needs UTF8 text so convert the Unicode character to an UTF8 string */
149	    uint32_t letter_buf[2];
150	    letter_buf[0] = lv_text_unicode_to_encoded(unicode_letter);
151	    letter_buf[1] = '\0';
152	
153	    const char * letter_buf_char = (const char *)letter_buf;
154	
155	#if LV_BIG_ENDIAN_SYSTEM
156	    while(*letter_buf_char == 0) ++letter_buf_char;
157	#endif
158	
159	    dsc->text = letter_buf_char;
160	    dsc->text_local = 1;
161	
162	    lv_draw_label(layer, dsc, &a);
163	    LV_PROFILER_DRAW_END;
164	}
