199	void lv_draw_label_iterate_characters(lv_draw_task_t * t, const lv_draw_label_dsc_t * dsc,
200	                                      const lv_area_t * coords,
201	                                      lv_draw_glyph_cb_t cb)
202	{
203	    const lv_font_t * font = dsc->font;
204	    int32_t w;
205	
206	    lv_area_t clipped_area;
207	    bool clip_ok = lv_area_intersect(&clipped_area, coords, &t->clip_area);
208	    if(!clip_ok) return;
209	
210	    lv_text_align_t align = dsc->align;
211	    lv_base_dir_t base_dir = dsc->bidi_dir;
212	
213	    lv_bidi_calculate_align(&align, &base_dir, dsc->text);
214	
215	    if((dsc->flag & LV_TEXT_FLAG_EXPAND) == 0) {
216	        /*Normally use the label's width as width*/
217	        w = lv_area_get_width(coords);
218	    }
219	    else {
220	        /*If EXPAND is enabled then not limit the text's width to the object's width*/
221	        w = dsc->text_size.x;
222	    }
223	
224	    int32_t line_height_font = lv_font_get_line_height(font);
225	    int32_t line_height = line_height_font + dsc->line_space;
226	
227	    /*Init variables for the first line*/
228	    int32_t line_width = 0;
229	    lv_point_t pos;
230	    lv_point_set(&pos, coords->x1, coords->y1);
231	
232	    int32_t x_ofs = 0;
233	    int32_t y_ofs = 0;
234	    x_ofs = dsc->ofs_x;
235	    y_ofs = dsc->ofs_y;
236	    pos.y += y_ofs;
237	
238	    uint32_t line_start     = 0;
239	    int32_t last_line_start = -1;
240	
241	    /*Check the hint to use the cached info*/
242	    if(dsc->hint && y_ofs == 0 && coords->y1 < 0) {
243	        /*If the label changed too much recalculate the hint.*/
244	        if(LV_ABS(dsc->hint->coord_y - coords->y1) > LV_LABEL_HINT_UPDATE_TH - 2 * line_height) {
245	            dsc->hint->line_start = -1;
246	        }
247	        last_line_start = dsc->hint->line_start;
248	    }
249	
250	    /*Use the hint if it's valid*/
251	    if(dsc->hint && last_line_start >= 0) {
252	        line_start = last_line_start;
253	        pos.y += dsc->hint->y;
254	    }
255	
256	    uint32_t remaining_len = dsc->text_length;
257	
258	    uint32_t line_end = line_start + lv_text_get_next_line(&dsc->text[line_start], remaining_len, font, dsc->letter_space,
259	                                                           w, NULL, dsc->flag);
260	
261	    /*Go the first visible line*/
262	    while(pos.y + line_height_font < t->clip_area.y1) {
263	        /*Go to next line*/
264	        line_start = line_end;
265	        line_end += lv_text_get_next_line(&dsc->text[line_start], remaining_len, font, dsc->letter_space, w, NULL, dsc->flag);
266	        pos.y += line_height;
267	
268	        /*Save at the threshold coordinate*/
269	        if(dsc->hint && pos.y >= -LV_LABEL_HINT_UPDATE_TH && dsc->hint->line_start < 0) {
270	            dsc->hint->line_start = line_start;
271	            dsc->hint->y          = pos.y - coords->y1;
272	            dsc->hint->coord_y    = coords->y1;
273	        }
274	
275	        if(dsc->text[line_start] == '\0') return;
276	    }
277	
278	    /*Align to middle*/
279	    if(align == LV_TEXT_ALIGN_CENTER) {
280	        line_width = lv_text_get_width_with_flags(&dsc->text[line_start], line_end - line_start, font, dsc->letter_space,
281	                                                  dsc->flag);
282	
283	        pos.x += (lv_area_get_width(coords) - line_width) / 2;
284	
285	    }
286	    /*Align to the right*/
287	    else if(align == LV_TEXT_ALIGN_RIGHT) {
288	        line_width = lv_text_get_width_with_flags(&dsc->text[line_start], line_end - line_start, font, dsc->letter_space,
289	                                                  dsc->flag);
290	        pos.x += lv_area_get_width(coords) - line_width;
291	    }
292	
293	    uint32_t sel_start = dsc->sel_start;
294	    uint32_t sel_end = dsc->sel_end;
295	    if(sel_start > sel_end) {
296	        uint32_t tmp = sel_start;
297	        sel_start = sel_end;
298	        sel_end = tmp;
299	    }
300	
301	    lv_area_t bg_coords;
302	    lv_draw_glyph_dsc_t draw_letter_dsc;
303	    lv_draw_glyph_dsc_init(&draw_letter_dsc);
304	    draw_letter_dsc.opa = dsc->opa;
305	    draw_letter_dsc.bg_coords = &bg_coords;
306	    draw_letter_dsc.color = dsc->color;
307	    draw_letter_dsc.rotation = dsc->rotation;
308	
309	    /* Set letter outline stroke attributes */
310	    draw_letter_dsc.outline_stroke_width = dsc->outline_stroke_width;
311	    draw_letter_dsc.outline_stroke_opa = dsc->outline_stroke_opa;
312	    draw_letter_dsc.outline_stroke_color = dsc->outline_stroke_color;
313	
314	    lv_draw_fill_dsc_t fill_dsc;
315	    lv_draw_fill_dsc_init(&fill_dsc);
316	    fill_dsc.opa = dsc->opa;
317	    int32_t underline_width = font->underline_thickness ? font->underline_thickness : 1;
318	    int32_t line_start_x;
319	    uint32_t next_char_offset;
320	    uint32_t recolor_command_start_index = 0;
321	    int32_t letter_w;
322	    cmd_state_t recolor_cmd_state = RECOLOR_CMD_STATE_WAIT_FOR_PARAMETER;
323	    lv_color_t recolor = lv_color_black(); /* Holds the selected color inside the recolor command */
324	    uint8_t is_first_space_after_cmd = 0;
325	
326	    /*Write out all lines*/
327	    while(remaining_len && dsc->text[line_start] != '\0') {
328	        pos.x += x_ofs;
329	        line_start_x = pos.x;
330	
331	        /*Write all letter of a line*/
332	        recolor_cmd_state = RECOLOR_CMD_STATE_WAIT_FOR_PARAMETER;
333	        next_char_offset = 0;
334	#if LV_USE_BIDI
335	        size_t bidi_size = line_end - line_start;
336	        char * bidi_txt = lv_malloc(bidi_size + 1);
337	        LV_ASSERT_MALLOC(bidi_txt);
338	
339	        /**
340	          * has_bided = 1: already executed lv_bidi_process_paragraph.
341	          * has_bided = 0: has not been executed lv_bidi_process_paragraph.*/
342	        if(dsc->has_bided) {
343	            lv_memcpy(bidi_txt, &dsc->text[line_start], bidi_size);
344	        }
345	        else {
346	            lv_bidi_process_paragraph(dsc->text + line_start, bidi_txt, bidi_size, base_dir, NULL, 0);
347	        }
348	#else
349	        const char * bidi_txt = dsc->text + line_start;
350	#endif
351	
352	        while(next_char_offset < remaining_len && next_char_offset < line_end - line_start) {
353	            uint32_t logical_char_pos = 0;
354	
355	            /* Check if the text selection is enabled */
356	            if(sel_start != LV_DRAW_LABEL_NO_TXT_SEL && sel_end != LV_DRAW_LABEL_NO_TXT_SEL) {
357	#if LV_USE_BIDI
358	                if(dsc->has_bided) {
359	                    logical_char_pos = lv_text_encoded_get_char_id(dsc->text, line_start + next_char_offset);
360	                }
361	                else {
362	                    logical_char_pos = lv_text_encoded_get_char_id(dsc->text, line_start);
363	                    uint32_t c_idx = lv_text_encoded_get_char_id(bidi_txt, next_char_offset);
364	                    logical_char_pos += lv_bidi_get_logical_pos(bidi_txt, NULL, line_end - line_start, base_dir, c_idx, NULL);
365	                }
366	#else
367	                logical_char_pos = lv_text_encoded_get_char_id(dsc->text, line_start + next_char_offset);
368	#endif
369	            }
370	
371	            uint32_t letter;
372	            uint32_t letter_next;
373	            lv_text_encoded_letter_next_2(bidi_txt, &letter, &letter_next, &next_char_offset);
374	
375	            /* If recolor is enabled */
376	            if((dsc->flag & LV_TEXT_FLAG_RECOLOR) != 0) {
377	
378	                if(letter == (uint32_t)LV_TXT_COLOR_CMD[0]) {
379	                    /* Handle the recolor command marker depending of the current recolor state */
380	
381	                    if(recolor_cmd_state == RECOLOR_CMD_STATE_WAIT_FOR_PARAMETER) {
382	                        recolor_command_start_index = next_char_offset;
383	                        recolor_cmd_state = RECOLOR_CMD_STATE_PARAMETER;
384	                        continue;
385	                    }
386	                    /*Other start char in parameter escaped cmd. char*/
387	                    else if(recolor_cmd_state == RECOLOR_CMD_STATE_PARAMETER) {
388	                        recolor_cmd_state = RECOLOR_CMD_STATE_WAIT_FOR_PARAMETER;
389	                    }
390	                    /* If letter is LV_TXT_COLOR_CMD and we were in the CMD_STATE_IN then the recolor close marked has been found */
391	                    else if(recolor_cmd_state == RECOLOR_CMD_STATE_TEXT_INPUT) {
392	                        recolor_cmd_state = RECOLOR_CMD_STATE_WAIT_FOR_PARAMETER;
393	                        continue;
394	                    }
395	                }
396	
397	                /* Find the first space (aka ' ') after the recolor command parameter, we need to skip rendering it */
398	                if((recolor_cmd_state == RECOLOR_CMD_STATE_PARAMETER) && (letter == ' ') && (is_first_space_after_cmd == 0)) {
399	                    is_first_space_after_cmd = 1;
400	                }
401	                else {
402	                    is_first_space_after_cmd = 0;
403	                }
404	
405	                /* Skip the color parameter and wait the space after it
406	                 * Once we have reach the space ' ', then we will extract the color information
407	                 * and store it into the recolor variable */
408	                if(recolor_cmd_state == RECOLOR_CMD_STATE_PARAMETER) {
409	                    /* Not an space? Continue with the next character */
410	                    if(letter != ' ') {
411	                        continue;
412	                    }
413	
414	                    /*Get the recolor parameter*/
415	                    if((next_char_offset - recolor_command_start_index) == LABEL_RECOLOR_PAR_LENGTH + 1) {
416	                        /* Temporary buffer to hold the recolor information */
417	                        char buf[LABEL_RECOLOR_PAR_LENGTH + 1];
418	                        lv_memcpy(buf, &bidi_txt[recolor_command_start_index], LABEL_RECOLOR_PAR_LENGTH);
419	                        buf[LABEL_RECOLOR_PAR_LENGTH] = '\0';
420	
421	                        uint8_t r, g, b;
422	                        r = (hex_char_to_num(buf[0]) << 4) + hex_char_to_num(buf[1]);
423	                        g = (hex_char_to_num(buf[2]) << 4) + hex_char_to_num(buf[3]);
424	                        b = (hex_char_to_num(buf[4]) << 4) + hex_char_to_num(buf[5]);
425	
426	                        recolor = lv_color_make(r, g, b);
427	                    }
428	                    else {
429	                        recolor.red = dsc->color.red;
430	                        recolor.blue = dsc->color.blue;
431	                        recolor.green = dsc->color.green;
432	                    }
433	
434	                    /*After the parameter the text is in the command*/
435	                    recolor_cmd_state = RECOLOR_CMD_STATE_TEXT_INPUT;
436	                }
437	
438	                /* Don't draw the first space after the recolor command */
439	                if(is_first_space_after_cmd) {
440	                    continue;
441	                }
442	            }
443	
444	            /* If we're in the CMD_STATE_IN state then we need to subtract the recolor command length */
445	            if(((dsc->flag & LV_TEXT_FLAG_RECOLOR) != 0) && (recolor_cmd_state == RECOLOR_CMD_STATE_TEXT_INPUT)) {
446	                logical_char_pos -= (LABEL_RECOLOR_PAR_LENGTH + 1);
447	            }
448	
449	            letter_w = lv_font_get_glyph_width(font, letter, letter_next);
450	
451	            /*Always set the bg_coordinates for placeholder drawing*/
452	            bg_coords.x1 = pos.x;
453	            bg_coords.y1 = pos.y;
454	            bg_coords.x2 = pos.x + letter_w - 1;
455	            bg_coords.y2 = pos.y + line_height - 1;
456	
457	            if(next_char_offset >= line_end - line_start) {
458	                if(dsc->decor & LV_TEXT_DECOR_UNDERLINE) {
459	                    lv_area_t fill_area;
460	                    fill_area.x1 = line_start_x;
461	                    fill_area.x2 = pos.x + letter_w - 1;
462	                    fill_area.y1 = pos.y + font->line_height - font->base_line - font->underline_position;
463	                    fill_area.y2 = fill_area.y1 + underline_width - 1;
464	
465	                    fill_dsc.color = dsc->color;
466	                    cb(t, NULL, &fill_dsc, &fill_area);
467	                }
468	                if(dsc->decor & LV_TEXT_DECOR_STRIKETHROUGH) {
469	                    lv_area_t fill_area;
470	                    fill_area.x1 = line_start_x;
471	                    fill_area.x2 = pos.x + letter_w - 1;
472	                    fill_area.y1 = pos.y + (font->line_height - font->base_line) * 2 / 3 + font->underline_thickness / 2;
473	                    fill_area.y2 = fill_area.y1 + underline_width - 1;
474	
475	                    fill_dsc.color = dsc->color;
476	                    cb(t, NULL, &fill_dsc, &fill_area);
477	                }
478	            }
479	
480	            /* Handle text selection */
481	            if(sel_start != LV_DRAW_LABEL_NO_TXT_SEL && sel_end != LV_DRAW_LABEL_NO_TXT_SEL
482	               && logical_char_pos >= sel_start && logical_char_pos < sel_end) {
483	                draw_letter_dsc.color = dsc->sel_color;
484	                fill_dsc.color = dsc->sel_bg_color;
485	                cb(t, NULL, &fill_dsc, &bg_coords);
486	            }
487	            else if(recolor_cmd_state == RECOLOR_CMD_STATE_TEXT_INPUT) {
488	                draw_letter_dsc.color = recolor;
489	            }
490	            else {
491	                draw_letter_dsc.color = dsc->color;
492	            }
493	
494	            lv_draw_unit_draw_letter(t, &draw_letter_dsc, &pos, font, letter, cb);
495	
496	            if(letter_w > 0) {
497	                pos.x += letter_w + dsc->letter_space;
498	            }
499	        }
500	
501	#if LV_USE_BIDI
502	        lv_free(bidi_txt);
503	        bidi_txt = NULL;
504	#endif
505	        /*Go to next line*/
506	        remaining_len -= line_end - line_start;
507	        line_start = line_end;
508	        if(remaining_len) {
509	            line_end += lv_text_get_next_line(&dsc->text[line_start], remaining_len, font, dsc->letter_space, w, NULL, dsc->flag);
510	        }
511	
512	        pos.x = coords->x1;
513	        /*Align to middle*/
514	        if(align == LV_TEXT_ALIGN_CENTER) {
515	            line_width =
516	                lv_text_get_width_with_flags(&dsc->text[line_start], line_end - line_start, font, dsc->letter_space, dsc->flag);
517	
518	            pos.x += (lv_area_get_width(coords) - line_width) / 2;
519	        }
520	        /*Align to the right*/
521	        else if(align == LV_TEXT_ALIGN_RIGHT) {
522	            line_width =
523	                lv_text_get_width_with_flags(&dsc->text[line_start], line_end - line_start, font, dsc->letter_space, dsc->flag);
524	            pos.x += lv_area_get_width(coords) - line_width;
525	        }
526	
527	        /*Go the next line position*/
528	        pos.y += line_height;
529	
530	        if(pos.y > t->clip_area.y2) break;
531	    }
532	
533	    if(draw_letter_dsc._draw_buf) lv_draw_buf_destroy(draw_letter_dsc._draw_buf);
534	
535	    LV_ASSERT_MEM_INTEGRITY();
536	}
