542	/**
543	 * Convert a hexadecimal characters to a number (0..15)
544	 * @param hex Pointer to a hexadecimal character (0..9, A..F)
545	 * @return the numerical value of `hex` or 0 on error
546	 */
547	static uint8_t hex_char_to_num(char hex)
548	{
549	    if(hex >= '0' && hex <= '9') return hex - '0';
550	    if(hex >= 'a') hex -= 'a' - 'A'; /*Convert to upper case*/
551	    return 'A' <= hex && hex <= 'F' ? hex - 'A' + 10 : 0;
552	}
