554	void lv_draw_unit_draw_letter(lv_draw_task_t * t, lv_draw_glyph_dsc_t * dsc,  const lv_point_t * pos,
555	                              const lv_font_t * font, uint32_t letter, lv_draw_glyph_cb_t cb)
556	{
557	    lv_font_glyph_dsc_t g;
558	
559	    if(lv_text_is_marker(letter)) /*Markers are valid letters but should not be rendered.*/
560	        return;
561	
562	    LV_PROFILER_DRAW_BEGIN;
563	    bool g_ret = lv_font_get_glyph_dsc(font, &g, letter, '\0');
564	    if(g_ret == false) {
565	        /*Add warning if the dsc is not found*/
566	        LV_LOG_WARN("lv_draw_letter: glyph dsc. not found for U+%" LV_PRIX32, letter);
567	    }
568	
569	    /*Don't draw anything if the character is empty. E.g. space*/
570	    if((g.box_h == 0) || (g.box_w == 0)) {
571	        LV_PROFILER_DRAW_END;
572	        return;
573	    }
574	
575	    lv_area_t letter_coords;
576	    letter_coords.x1 = pos->x + g.ofs_x;
577	    letter_coords.x2 = letter_coords.x1 + g.box_w - 1;
578	    letter_coords.y1 = pos->y + (font->line_height - font->base_line) - g.box_h - g.ofs_y;
579	    letter_coords.y2 = letter_coords.y1 + g.box_h - 1;
580	    lv_area_move(&letter_coords, -dsc->pivot.x, -dsc->pivot.y);
581	
582	    /*If the letter is completely out of mask don't draw it*/
583	    if(lv_area_is_out(&letter_coords, &t->clip_area, 0) &&
584	       dsc->bg_coords &&
585	       lv_area_is_out(dsc->bg_coords, &t->clip_area, 0)) {
586	        LV_PROFILER_DRAW_END;
587	        return;
588	    }
589	
590	    if(g.resolved_font) {
591	        lv_draw_buf_t * draw_buf = NULL;
592	        if(LV_FONT_GLYPH_FORMAT_NONE < g.format && g.format < LV_FONT_GLYPH_FORMAT_IMAGE) {
593	            /*Only check draw buf for bitmap glyph*/
594	            draw_buf = lv_draw_buf_reshape(dsc->_draw_buf, 0, g.box_w, g.box_h, LV_STRIDE_AUTO);
595	            if(draw_buf == NULL) {
596	                if(dsc->_draw_buf) lv_draw_buf_destroy(dsc->_draw_buf);
597	
598	                uint32_t h = g.box_h;
599	                if(h * g.box_w < 64) h *= 2; /*Alloc a slightly larger buffer*/
600	                draw_buf = lv_draw_buf_create_ex(font_draw_buf_handlers, g.box_w, h, LV_COLOR_FORMAT_A8, LV_STRIDE_AUTO);
601	                LV_ASSERT_MALLOC(draw_buf);
602	                draw_buf->header.h = g.box_h;
603	                dsc->_draw_buf = draw_buf;
604	            }
605	        }
606	
607	        dsc->format = g.format;
608	
609	        if(g.format == LV_FONT_GLYPH_FORMAT_VECTOR) {
610	
611	            /*Load the outline of the glyph, even if the function says bitmap*/
612	            g.outline_stroke_width = dsc->outline_stroke_width;
613	            dsc->glyph_data = (void *) lv_font_get_glyph_bitmap(&g, draw_buf);
614	            dsc->format = dsc->glyph_data ? g.format : LV_FONT_GLYPH_FORMAT_NONE;
615	        }
616	    }
617	    else {
618	        dsc->format = LV_FONT_GLYPH_FORMAT_NONE;
619	    }
620	
621	    dsc->letter_coords = &letter_coords;
622	    dsc->g = &g;
623	    cb(t, dsc, NULL, NULL);
624	
625	    lv_font_glyph_release_draw_data(&g);
626	
627	    LV_PROFILER_DRAW_END;
628	}
