751	static void lv_label_event(const lv_obj_class_t * class_p, lv_event_t * e)
752	{
753	    LV_UNUSED(class_p);
754	
755	    /*Call the ancestor's event handler*/
756	    const lv_result_t res = lv_obj_event_base(MY_CLASS, e);
757	    if(res != LV_RESULT_OK) return;
758	
759	    const lv_event_code_t code = lv_event_get_code(e);
760	    lv_obj_t * obj = lv_event_get_current_target(e);
761	
762	    if((code == LV_EVENT_STYLE_CHANGED) || (code == LV_EVENT_SIZE_CHANGED)) {
763	        lv_label_refr_text(obj);
764	    }
765	    else if(code == LV_EVENT_REFR_EXT_DRAW_SIZE) {
766	        /* Italic or other non-typical letters can be drawn of out of the object.
767	         * It happens if box_w + ofs_x > adw_w in the glyph.
768	         * To avoid this add some extra draw area.
769	         * font_h / 4 is an empirical value. */
770	        const lv_font_t * font = lv_obj_get_style_text_font(obj, LV_PART_MAIN);
771	        const int32_t font_h = lv_font_get_line_height(font);
772	        lv_event_set_ext_draw_size(e, font_h / 4);
773	    }
774	    else if(code == LV_EVENT_GET_SELF_SIZE) {
775	        lv_label_t * label = (lv_label_t *)obj;
776	        if(label->invalid_size_cache) {
777	            const lv_font_t * font = lv_obj_get_style_text_font(obj, LV_PART_MAIN);
778	            int32_t letter_space = lv_obj_get_style_text_letter_space(obj, LV_PART_MAIN);
779	
780	            int32_t line_space = lv_obj_get_style_text_line_space(obj, LV_PART_MAIN);
781	            lv_text_flag_t flag = LV_TEXT_FLAG_NONE;
782	            if(label->recolor != 0) flag |= LV_TEXT_FLAG_RECOLOR;
783	            if(label->expand != 0) flag |= LV_TEXT_FLAG_EXPAND;
784	
785	            int32_t w;
786	            if(lv_obj_get_style_width(obj, LV_PART_MAIN) == LV_SIZE_CONTENT && !obj->w_layout) w = LV_COORD_MAX;
787	            else w = lv_obj_get_content_width(obj);
788	            w = LV_MIN(w, lv_obj_get_style_max_width(obj, LV_PART_MAIN));
789	
790	            uint32_t dot_begin = label->dot_begin;
791	            lv_label_revert_dots(obj);
792	            lv_text_get_size(&label->size_cache, label->text, font, letter_space, line_space, w, flag);
793	            lv_label_set_dots(obj, dot_begin);
794	
795	            label->size_cache.y = LV_MIN(label->size_cache.y, lv_obj_get_style_max_height(obj, LV_PART_MAIN));
796	
797	            label->invalid_size_cache = false;
798	        }
799	
800	        lv_point_t * self_size = lv_event_get_param(e);
801	        self_size->x = LV_MAX(self_size->x, label->size_cache.x);
802	        self_size->y = LV_MAX(self_size->y, label->size_cache.y);
803	    }
804	    else if(code == LV_EVENT_DRAW_MAIN) {
805	        draw_main(e);
806	    }
807	}
