942	/**
943	 * Refresh the label with its text stored in its extended data
944	 * @param label pointer to a label object
945	 */
946	static void lv_label_refr_text(lv_obj_t * obj)
947	{
948	    lv_label_t * label = (lv_label_t *)obj;
949	    if(label->text == NULL) return;
950	#if LV_LABEL_LONG_TXT_HINT
951	    label->hint.line_start = -1; /*The hint is invalid if the text changes*/
952	#endif
953	    label->invalid_size_cache = true;
954	
955	    lv_area_t txt_coords;
956	    lv_obj_get_content_coords(obj, &txt_coords);
957	    int32_t max_w         = lv_area_get_width(&txt_coords);
958	    const lv_font_t * font   = lv_obj_get_style_text_font(obj, LV_PART_MAIN);
959	    int32_t line_space = lv_obj_get_style_text_line_space(obj, LV_PART_MAIN);
960	    int32_t letter_space = lv_obj_get_style_text_letter_space(obj, LV_PART_MAIN);
961	
962	    /*Calc. the height and longest line*/
963	    lv_point_t size;
964	    lv_text_flag_t flag = get_label_flags(label);
965	
966	    lv_label_revert_dots(obj);
967	    lv_text_get_size(&size, label->text, font, letter_space, line_space, max_w, flag);
968	    label->text_size = size;
969	
970	    lv_obj_refresh_self_size(obj);
971	
972	    /*In scroll mode start an offset animation*/
973	    if(label->long_mode == LV_LABEL_LONG_MODE_SCROLL) {
974	        const lv_anim_t * anim_template = lv_obj_get_style_anim(obj, LV_PART_MAIN);
975	        uint32_t anim_time = lv_obj_get_style_anim_duration(obj, LV_PART_MAIN);
976	        if(anim_time == 0) anim_time = LV_LABEL_DEF_SCROLL_SPEED;
977	        lv_anim_t a;
978	        lv_anim_init(&a);
979	        lv_anim_set_var(&a, obj);
980	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
981	        lv_anim_set_reverse_delay(&a, LV_LABEL_SCROLL_DELAY);
982	        lv_anim_set_repeat_delay(&a, a.reverse_delay);
983	
984	        bool hor_anim = false;
985	        if(size.x > lv_area_get_width(&txt_coords)) {
